// Utility: read a binary file into a vector of vectors
template<typename T>
std::vector<std::vector<T>> read2vecs(std::filesystem::path fname, int record_dim) {
  std::ifstream file(fname, std::ios::binary);
  if (!file.is_open()) throw std::runtime_error("Cannot open " + fname.string());
  file.seekg(0, std::ios::end);
  auto nbytes = file.tellg();
  file.seekg(0, std::ios::beg);
  auto nrecords = nbytes / (record_dim * sizeof(T));
  std::vector<std::vector<T>> result(nrecords);
  for (auto& r : result) {
    r.resize(record_dim);
    file.read(reinterpret_cast<char*>(r.data()), record_dim * sizeof(T));
  }
  return result;
}

template<typename T>
std::vector<T> read1vec(std::filesystem::path fname, int dim) {
  auto vecs = read2vecs<T>(fname, dim);
  if (vecs.empty()) return {};
  return vecs[0];
}

// Utility: read a text file (space-separated) into a vector of vectors
template<typename T>
std::vector<std::vector<T>> read_text_matrix(std::filesystem::path fname, int record_dim) {
  std::ifstream file(fname);
  if (!file.is_open()) throw std::runtime_error("Cannot open " + fname.string());
  std::vector<std::vector<T>> result;
  std::string line;
  while (std::getline(file, line)) {
    if (line.empty()) continue;
    std::istringstream iss(line);
    std::vector<T> row;
    T val;
    while (iss >> val) row.push_back(val);
    if ((int)row.size() >= record_dim) row.resize(record_dim);
    result.push_back(std::move(row));
  }
  return result;
}

template<typename T>
void write2disk(const std::vector<std::vector<T>>& data, std::filesystem::path fname) {
  std::ofstream file(fname, std::ios::binary);
  if (!file.is_open()) throw std::runtime_error("Cannot open " + fname.string());
  for (const auto& r : data)
    file.write(reinterpret_cast<const char*>(r.data()), r.size() * sizeof(T));
}

template<typename T>
void write2disk(const std::vector<T>& data, std::filesystem::path fname) {
  std::ofstream file(fname, std::ios::binary);
  if (!file.is_open()) throw std::runtime_error("Cannot open " + fname.string());
  file.write(reinterpret_cast<const char*>(data.data()), data.size() * sizeof(T));
}

template<typename T>
std::vector<std::vector<T>> transpose_matrix(const std::vector<std::vector<T>>& m) {
  if (m.empty()) return {};
  size_t rows = m.size(), cols = m[0].size();
  std::vector<std::vector<T>> result(cols, std::vector<T>(rows));
  for (size_t i = 0; i < rows; i++)
    for (size_t j = 0; j < cols; j++) result[j][i] = m[i][j];
  return result;
}

template<typename T>
std::vector<std::vector<std::vector<T>>> batch_rows(
    const std::vector<std::vector<T>>& data, size_t batch_size) {
  std::vector<std::vector<std::vector<T>>> result;
  for (size_t i = 0; i < data.size(); i += batch_size) {
    size_t end = std::min(i + batch_size, data.size());
    result.emplace_back(data.begin() + i, data.begin() + end);
  }
  return result;
}

template<typename T>
std::vector<T> tile(const std::vector<T>& v, size_t n) {
  std::vector<T> result(n);
  for (size_t i = 0; i < n; i++) result[i] = v[i % v.size()];
  return result;
}

template<typename T, typename V>
std::vector<std::vector<T>> prepend_column(
    const std::vector<std::vector<T>>& data, V val) {
  std::vector<std::vector<T>> result;
  for (const auto& row : data) {
    std::vector<T> r = {static_cast<T>(val)};
    r.insert(r.end(), row.begin(), row.end());
    result.push_back(r);
  }
  return result;
}

template<typename T>
std::vector<std::vector<std::vector<double>>> scale_batched(
    const std::vector<std::vector<std::vector<T>>>& batches, double factor) {
  std::vector<std::vector<std::vector<double>>> result;
  for (auto& batch : batches) {
    result.push_back({});
    for (auto& row : batch) {
      result.back().push_back({});
      for (auto& val : row) result.back().back().push_back(val * factor);
    }
  }
  return result;
}

