using Slots = std::vector<double>;
inline Slots add(Slots a, const Slots& b) {
  if (a.size() < b.size()) a.resize(b.size(), 0.0);
  for (size_t i = 0; i < b.size(); ++i) a[i] += b[i]; return a; }
inline Slots add(Slots a, double s) { for (auto& x : a) x += s; return a; }
inline Slots sub(Slots a, const Slots& b) {
  if (a.size() < b.size()) a.resize(b.size(), 0.0);
  for (size_t i = 0; i < b.size(); ++i) a[i] -= b[i]; return a; }
inline Slots sub(Slots a, double s) { for (auto& x : a) x -= s; return a; }
inline Slots mul(const Slots& a, const Slots& b) {
  Slots r(std::min(a.size(), b.size()));
  for (size_t i = 0; i < r.size(); ++i) r[i] = a[i] * b[i]; return r; }
inline Slots mul(Slots a, double s) { for (auto& x : a) x *= s; return a; }
inline Slots nullsafe_add(const Slots& a, const Slots& b) {
  return a.empty() ? b : add(a, b); }
inline Slots negate(Slots a) { for (auto& x : a) x = -x; return a; }
inline Slots rotate(Slots a, int k) {  // EvalRotate: +k rotates left
  if (a.empty()) return a;
  k = ((k % (int)a.size()) + (int)a.size()) % (int)a.size();
  std::rotate(a.begin(), a.begin() + k, a.end()); return a; }
inline Slots slot_sum(const Slots& a, size_t n) {  // EvalSum semantics
  double s = 0.0;
  for (size_t i = 0; i < std::min(n, a.size()); ++i) s += a[i];
  return Slots(a.empty() ? n : a.size(), s); }
template <typename F> inline Slots apply(Slots a, F f) {
  for (auto& x : a) x = f(x); return a; }
inline Slots read_slots(const std::filesystem::path& p) {
  std::ifstream f(p, std::ios::binary);
  if (!f.is_open()) throw std::runtime_error("cannot open " + p.string());
  f.seekg(0, std::ios::end); auto n = f.tellg() / sizeof(double);
  f.seekg(0, std::ios::beg); Slots v(n);
  f.read(reinterpret_cast<char*>(v.data()), n * sizeof(double)); return v; }
inline void write_slots(const std::filesystem::path& p, const Slots& v) {
  std::filesystem::create_directories(p.parent_path());
  std::ofstream f(p, std::ios::binary);
  f.write(reinterpret_cast<const char*>(v.data()), v.size() * sizeof(double)); }
