inline Ciphertext<DCRTPoly> NullSafeEvalAdd(
    CryptoContext<DCRTPoly> cc, Ciphertext<DCRTPoly> a, Ciphertext<DCRTPoly> b) {
  if (a == nullptr) return b;
  return cc->EvalAdd(a, b);
}

inline std::vector<double> slot_mask(size_t n_slots, size_t n_cols,
                                     size_t row_start, size_t row_end) {
  std::vector<double> mask(n_slots, 0.0);
  for (size_t col = 0; col < n_cols; col++)
    for (size_t row = row_start; row < row_end; row++)
      mask[col + row * n_cols] = 1.0;
  return mask;
}

