template<typename T>
std::vector<T> vector_union(std::vector<std::vector<T>>& vecs) {
  std::set<T> s;
  for (const auto& v : vecs) s.insert(v.begin(), v.end());
  return std::vector<T>(s.begin(), s.end());
}

